with metrics as (select *, avg(shipping_fee) over (partition by store_id order by order_date, id rows between unbounded preceding and current row) as running_avg_shipping_fee, sum(shipping_fee) over (partition by store_id order by order_date, id rows between unbounded preceding and current row) as running_sum_shipping_fee, max(shipping_fee) over (partition by store_id order by order_date, id rows between unbounded preceding and current row) as running_max_shipping_fee, count(shipping_fee) over (partition by store_id order by order_date, id rows between unbounded preceding and current row) as running_count_shipping_fee, lag(discount, 1) over (partition by channel, customer_id order by discount, id) as prev_discount from orders where amount > 1400) select date_trunc('quarter', order_date) as quarter_start, date_trunc('month', order_date) as activity_month, percentile_approx(running_count_shipping_fee, 0.95) as running_count_shipping_fee_p95, round(avg(amount), 2) as avg_amount, count(distinct store_id) as distinct_store_ids from metrics group by 1, 2 order by quarter_start desc nulls first;
